<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {ChevronLeft,ChevronRight,ZoomIn,ZoomOut,RotateCcw,PanelLeft,X} from 'lucide-vue-next';import {imageSource,type Publication} from '../../services/store';
const props=defineProps<{publication:Publication}>();const emit=defineEmits<{position:[value:number];reselect:[]}>();const index=ref(Math.max(0,props.publication.position-1)),zoom=ref(1),pan=ref({x:0,y:0}),panel=ref(false),failed=ref(false),dragging=ref(false);const item=computed(()=>props.publication.images[index.value]),source=computed(()=>imageSource(props.publication,index.value));let pointer={x:0,y:0};function go(n:number){index.value=Math.max(0,Math.min(props.publication.images.length-1,n));zoom.value=1;pan.value={x:0,y:0};failed.value=false;emit('position',index.value+1);if(window.innerWidth<800)panel.value=false}function start(e:PointerEvent){if(zoom.value<=1)return;e.preventDefault();(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);dragging.value=true;pointer={x:e.clientX-pan.value.x,y:e.clientY-pan.value.y}}function move(e:PointerEvent){if(dragging.value)pan.value={x:e.clientX-pointer.x,y:e.clientY-pointer.y}}function stop(){dragging.value=false}function reset(){zoom.value=1;pan.value={x:0,y:0}}function keyboard(e:KeyboardEvent){if((e.target as HTMLElement).closest('input,select,textarea,button'))return;if(e.key==='ArrowRight')go(index.value+1);if(e.key==='ArrowLeft')go(index.value-1);if(e.key==='Escape')panel.value=false}watch(zoom,v=>{if(v===1)pan.value={x:0,y:0}});watch(source,()=>failed.value=false);onMounted(()=>document.addEventListener('keydown',keyboard));onBeforeUnmount(()=>document.removeEventListener('keydown',keyboard));
</script>
<template><div class="album-reader"><div class="album-toolbar"><button class="icon-button" aria-label="Open album thumbnails" :aria-expanded="panel" @click="panel=!panel"><PanelLeft :size="18"/></button><div class="row"><button class="icon-button" aria-label="Previous image" :disabled="index===0" @click="go(index-1)"><ChevronLeft :size="18"/></button><span class="small">{{index+1}} / {{publication.images.length}}</span><button class="icon-button" aria-label="Next image" :disabled="index===publication.images.length-1" @click="go(index+1)"><ChevronRight :size="18"/></button></div><div class="row"><button class="icon-button" aria-label="Zoom out" :disabled="zoom<=1" @click="zoom=Math.max(1,zoom-.5)"><ZoomOut :size="18"/></button><span class="small">{{zoom*100}}%</span><button class="icon-button" aria-label="Zoom in" :disabled="zoom>=4" @click="zoom=Math.min(4,zoom+.5)"><ZoomIn :size="18"/></button><button class="icon-button" aria-label="Reset image zoom and position" @click="reset"><RotateCcw :size="18"/></button></div></div><div class="album-workspace"><aside v-if="panel" class="album-panel"><div class="row between"><h3>Images</h3><button class="icon-button" aria-label="Close album thumbnails" @click="panel=false"><X :size="18"/></button></div><button v-for="(image,n) in publication.images" :key="image.id" class="album-thumb" :class="{selected:n===index}" @click="go(n)"><img v-if="imageSource(publication,n)" :src="imageSource(publication,n)" :alt="image.alt"/><span>{{n+1}}. {{image.caption||'Untitled image'}}</span></button></aside><div class="image-stage" :class="{pannable:zoom>1,dragging}" @pointerdown="start" @pointermove="move" @pointerup="stop" @pointercancel="stop"><div v-if="!source||failed" class="image-missing"><h2>Image unavailable</h2><p>This image is no longer available in this browser session.</p><button class="button" @click="emit('reselect')">Select images again</button></div><img v-else :key="source" class="main-image" :src="source" :alt="item?.alt||'Album image'" draggable="false" :style="{transform:`translate(${pan.x}px, ${pan.y}px) scale(${zoom})`}" @error="failed=true"/></div></div><footer class="album-caption"><p>{{item?.caption||'Untitled image'}}</p><span class="small muted">{{zoom>1?'Drag the image to move around.':'Use the arrows to explore this album.'}}</span></footer></div></template>
<style scoped>.album-reader{display:flex;flex-direction:column;height:100%;min-height:0}.album-toolbar{padding:12px 24px;display:flex;align-items:center;justify-content:space-between;gap:16px;background:var(--surface);border-bottom:1px solid var(--border)}.album-toolbar .icon-button,.album-panel .icon-button{display:flex;align-items:center;justify-content:center}.album-workspace{display:flex;min-height:0;position:relative;flex:1}.image-stage{flex:1;min-width:0;overflow:hidden;position:relative;display:flex;align-items:center;justify-content:center;padding:40px;background:#e7ebe3;user-select:none}.main-image{max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;transform-origin:center;box-shadow:0 4px 16px #00000012;pointer-events:none}.image-stage.pannable{cursor:grab;touch-action:none}.image-stage.dragging{cursor:grabbing}.album-caption{text-align:center;padding:20px;background:var(--surface);border-top:1px solid var(--border)}.album-caption p{margin:0 0 4px;font-size:18px}.album-panel{padding:20px;overflow:auto;flex-shrink:0;width:240px;border-right:1px solid var(--border);background:var(--surface)}.album-panel h3{font-size:18px;margin:0}.album-thumb{display:flex;flex-direction:column;padding:12px;border:1px solid transparent;background:none;border-radius:8px;gap:12px;font-size:12px;text-align:left;width:100%;margin:12px 0}.album-thumb img{width:100%;height:100px;object-fit:cover;border-radius:4px}.album-thumb.selected{border-color:#859885;background:#edf2e9}.image-missing{text-align:center;background:var(--surface);padding:32px;border-radius:12px;max-width:400px}@media(max-width:800px){.album-panel{position:absolute;inset:0 auto 0 0;z-index:5;width:min(290px,90%);box-shadow:8px 0 20px #0001}.image-stage{padding:20px}.album-toolbar{padding:10px;gap:8px}.album-toolbar>.row{gap:6px}.album-toolbar .icon-button{min-width:44px}}@media(max-width:390px){.album-toolbar{flex-wrap:wrap;justify-content:center}.album-toolbar>.icon-button{margin-right:auto}.album-toolbar>.row:last-child{margin-left:auto}.album-caption{padding:16px}.album-caption p{font-size:16px}.image-stage{padding:12px}}
</style>
